From 60a0f78fe69f4c8ebda3c19ab0b1776ee2411ac3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:35:23 +0100
Subject: [PATCH] libtaskmanager: allow dragging grouped tasks to another
 desktop

Grouped tasks offered no drag data and a mime type that Wayland tasks
don't recognize, so dropping a group on the Pager did nothing. Groups now
carry their windows' ids in the Wayland group format, which is parsed.

BUG: 456041
---
 libtaskmanager/taskgroupingproxymodel.cpp | 19 ++++++++++++++-----
 libtaskmanager/waylandtasksmodel.cpp      | 16 +++++++++++++---
 2 files changed, 27 insertions(+), 8 deletions(-)

diff --git a/libtaskmanager/taskgroupingproxymodel.cpp b/libtaskmanager/taskgroupingproxymodel.cpp
index 82709a40c9..fd5acadb04 100644
--- a/libtaskmanager/taskgroupingproxymodel.cpp
+++ b/libtaskmanager/taskgroupingproxymodel.cpp
@@ -680,12 +680,21 @@ QVariant TaskGroupingProxyModel::data(const QModelIndex &proxyIndex, int role) c
             return winIds;
         }

-        case AbstractTasksModel::MimeType:
-            return QStringLiteral("windowsystem/multiple-winids");
+        case AbstractTasksModel::MimeType: {
+            QString mimeType = index(0, 0, proxyIndex).data(AbstractTasksModel::MimeType).toString();
+            mimeType.replace(QLatin1String("windowsystem/winid"), QLatin1String("windowsystem/multiple-winids"));
+            return mimeType;
+        }

-        case AbstractTasksModel::MimeData:
-            // FIXME TODO: Implement.
-            return {};
+        case AbstractTasksModel::MimeData: {
+            QStringList data;
+
+            for (int i = 0; i < rowCount(proxyIndex); ++i) {
+                data.append(index(i, 0, proxyIndex).data(AbstractTasksModel::MimeData).toString());
+            }
+
+            return data.join(QLatin1Char('\n'));
+        }

         case AbstractTasksModel::IsGroupParent:
             return true;
diff --git a/libtaskmanager/waylandtasksmodel.cpp b/libtaskmanager/waylandtasksmodel.cpp
index ed0b90cbbf..4911f65dbb 100644
--- a/libtaskmanager/waylandtasksmodel.cpp
+++ b/libtaskmanager/waylandtasksmodel.cpp
@@ -1368,9 +1368,19 @@ QList<QUuid> WaylandTasksModel::winIdsFromMimeData(const QMimeData *mimeData, bo
         return ids;
     }

-    // FIXME: Extracting multiple winids is still unimplemented;
-    // TaskGroupingProxy::data(..., ::MimeData) can't produce
-    // a payload with them anyways.
+    const QList<QByteArray> lines = mimeData->data(Private::groupMimeType()).split('\n');
+
+    for (const QByteArray &line : lines) {
+        const QUuid id(line);
+
+        if (!id.isNull()) {
+            ids << id;
+        }
+    }
+
+    if (ok) {
+        *ok = !ids.isEmpty();
+    }

     return ids;
 }
